  novita: [
    { titolo: "D.L. 48/2025 (conv. L. 80/2025) – blocco stradale", testo: "Il blocco stradale realizzato con il proprio corpo, prima illecito amministrativo, diventa reato (art. 1-bis D.Lgs. 66/1948), con pena aggravata se commesso da più persone riunite. Rilevante quando una manifestazione invade la carreggiata.", stato: "da verificare", fonte: "G.U. 11/4/2025 (D.L.) e G.U. 9/6/2025 (L. 80/2025)" },
    { titolo: "L. 40/2025 – delega per la revisione del Codice di protezione civile", testo: "Legge delega per aggiornare il D.Lgs. 1/2018 (tra i temi: rafforzamento della pianificazione, gestione delle emergenze e della ricostruzione). Verificare se sono stati adottati i decreti legislativi attuativi entro fine 2026.", stato: "da verificare", fonte: "G.U. 2025 – Normattiva" },
    { titolo: "Accordo Stato-Regioni 17 aprile 2025 sulla formazione", testo: "Accordo unico che riordina durata, contenuti e verifiche della formazione di lavoratori, preposti, dirigenti e datori di lavoro (art. 37 D.Lgs. 81/2008), con introduzione della formazione obbligatoria per il datore di lavoro e periodo transitorio.", stato: "da verificare", fonte: "Conferenza Stato-Regioni, rep. atti n. 59/CSR; G.U. maggio 2025" },
    { titolo: "D.L. 19/2024 (conv. L. 56/2024) – patente a crediti", testo: "Dal 1° ottobre 2024 imprese e lavoratori autonomi che operano nei cantieri temporanei o mobili devono possedere la patente a crediti (nuovo art. 27 D.Lgs. 81/2008). Utile nei controlli congiunti nei cantieri.", stato: "verificato", fonte: "G.U. 2/3/2024 e 30/4/2024" },
    { titolo: "D.L. 159/2025 – misure urgenti su salute e sicurezza nei luoghi di lavoro", testo: "Decreto dell'autunno 2025 con interventi su vigilanza, formazione, badge di cantiere e premialità INAIL. Controllare legge di conversione e testo coordinato prima di citarlo.", stato: "da verificare", fonte: "G.U. ottobre 2025 – Normattiva" },
    { titolo: "D.L. 146/2021 – preposto e vigilanza", testo: "Obbligo di individuare il preposto (art. 18, c. 1, lett. b-bis), nuovi poteri di intervento e interruzione (art. 19), competenza di vigilanza dell'INL estesa a tutti i settori (art. 13).", stato: "verificato", fonte: "L. 215/2021" },
    { titolo: "Allertamento in Toscana e IT-alert", testo: "Il sistema regionale (Centro funzionale e LaMMA, codici verde-giallo-arancione-rosso) resta disciplinato dalla D.G.R.T. 395/2015 e successivi aggiornamenti; IT-alert è operativo a livello nazionale per i messaggi alla popolazione. Verificare sul sito regionale l'ultima delibera sul sistema di allertamento.", stato: "da verificare", fonte: "regione.toscana.it/allertameteo; it-alert.gov.it" }
  ],

  flash: [
    ["Entro quanto i provvedimenti provvisori di PS sulla libertà personale vanno comunicati all'AG?", "Entro 48 ore; convalida entro le successive 48, altrimenti revocati e privi di effetto (art. 13 Cost.)."],
    ["Termini del sequestro d'urgenza della stampa?", "Denuncia all'AG entro 24 ore e convalida entro le successive 24 (art. 21 Cost.)."],
    ["Per quale riunione serve il preavviso?", "Solo in luogo pubblico; al Questore almeno 3 giorni prima (art. 17 Cost.; art. 18 TULPS)."],
    ["Per quali motivi si può limitare la libertà di circolazione?", "Sanità o sicurezza, con legge in via generale; mai per ragioni politiche (art. 16 Cost.)."],
    ["Differenza tra riserva di legge e riserva di giurisdizione?", "La prima esige che la legge disciplini la limitazione; la seconda che la singola restrizione sia disposta con atto motivato del giudice (artt. 13, 14, 15, 21 Cost.)."],
    ["Cosa stabilisce l'art. 28 Cost.?", "Responsabilità diretta di funzionari e dipendenti per atti lesivi di diritti; la responsabilità civile si estende allo Stato e agli enti pubblici."],
    ["Principi dell'art. 118 Cost.?", "Funzioni amministrative ai Comuni; sussidiarietà, differenziazione, adeguatezza; sussidiarietà orizzontale (c. 4)."],
    ["La polizia amministrativa locale è materia statale?", "No: l'art. 117, c. 2, lett. h la esclude dall'ordine pubblico statale; è materia regionale residuale."],
    ["Cosa presume l'art. 2054, c. 2 c.c.?", "Nello scontro tra veicoli, concorso di colpa uguale dei conducenti fino a prova contraria."],
    ["Prescrizione del risarcimento da circolazione?", "2 anni (art. 2947, c. 2 c.c.), salvo termine più lungo se il fatto è reato."],
    ["Termine per il ricorso al TAR?", "60 giorni per la notifica, deposito entro 30 giorni (artt. 29 e 45 c.p.a.)."],
    ["Ricorso straordinario al Presidente della Repubblica?", "120 giorni, solo legittimità, alternativo al TAR (D.P.R. 1199/1971)."],
    ["Chi è autorità territoriale di protezione civile nel Comune?", "Il Sindaco (artt. 3, 6 e 12 D.Lgs. 1/2018)."],
    ["Durata dello stato di emergenza nazionale?", "Max 12 mesi, prorogabile per non più di altri 12 (art. 24 D.Lgs. 1/2018)."],
    ["Obblighi non delegabili del datore di lavoro?", "Valutazione dei rischi con DVR e designazione dell'RSPP (art. 17 D.Lgs. 81/2008)."]
  ],

